Write Kotest tests for this Kotlin class using TDD principles:

```kotlin
class DiscountCalculator {
    fun calculate(orderTotal: Double, couponCode: String?): Double {
        if (couponCode == null) return orderTotal
        return when (couponCode) {
            "SAVE10" -> orderTotal * 0.90
            "SAVE20" -> orderTotal * 0.80
            "HALFOFF" -> orderTotal * 0.50
            else -> throw IllegalArgumentException("Unknown coupon: $couponCode")
        }
    }
}
```

Make sure the tests cover happy path, edge cases, and the exception case. Use FunSpec.

Review this Kotlin test and tell me what anti-patterns it has:

```kotlin
class UserServiceTest : FunSpec({
    val repo = mockk<UserRepository>()
    val emailGateway = mockk<EmailGateway>()
    val sut = UserService(repo, emailGateway)

    test("RegisterUser_ValidInput_ReturnsUser") {
        val userId = "abc-123"
        val request = CreateUserRequest(name = "Alice", email = "alice@example.com")
        val expected = User(id = userId, name = request.name, email = request.email)

        coEvery { repo.save(any()) } just Runs
        coEvery { emailGateway.send(any()) } just Runs
        coEvery { repo.findById(userId) } returns expected

        sut.register(request)

        coVerify { repo.save(any()) }
        coVerify { repo.findById(any()) }  // verify stub was called
        coVerify(exactly = 1) { emailGateway.send(match { it.to == "alice@example.com" }) }
    }
})
```

